import{_ as a,o as t,c as r,a2 as o}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"安全中心 - 安全设置","description":"","frontmatter":{"title":"安全中心 - 安全设置"},"headers":[],"relativePath":"ops-knowledge-base/presales-support/security-settings.md","filePath":"ops-knowledge-base/presales-support/security-settings.md","lastUpdated":1788259091000}'),s={name:"ops-knowledge-base/presales-support/security-settings.md"};function i(n,e,l,p,d,c){return t(),r("div",null,[...e[0]||(e[0]=[o('<h2 id="一、概述" tabindex="-1">一、概述 <a class="header-anchor" href="#一、概述" aria-label="Permalink to &quot;一、概述&quot;">​</a></h2><p>在平台的安全设置体系中，两步验证功能是提升账户安全性的重要保障措施。它通过双因素身份验证机制，为用户登录账户增加了额外的安全层级，有效防范未授权访问，保障用户账户及相关信息的安全。</p><h2 id="二、功能入口" tabindex="-1">二、功能入口 <a class="header-anchor" href="#二、功能入口" aria-label="Permalink to &quot;二、功能入口&quot;">​</a></h2><p>用户可通过 “后台右上角头像/安全中心” 路径，进入安全设置界面，找到两步验证功能设置区域。</p><h2 id="三、功能说明" tabindex="-1">三、功能说明 <a class="header-anchor" href="#三、功能说明" aria-label="Permalink to &quot;三、功能说明&quot;">​</a></h2><h3 id="一-两步验证功能定义" tabindex="-1">（一）两步验证功能定义 <a class="header-anchor" href="#一-两步验证功能定义" aria-label="Permalink to &quot;（一）两步验证功能定义&quot;">​</a></h3><p>两步验证，即双因素身份验证，为用户登录提供了额外的一层保护。一旦启用并配置该功能，每次用户登录时，除了需要输入用户名和密码外，还需提供两步验证代码，如安全码、时间令牌，或从 Google Authenticator、Duo 等专门的身份验证应用程序获取的动态代码。通过这种双重验证方式，极大地增加了账户被非法入侵的难度，显著提升账户安全性。</p><h3 id="二-功能启用操作" tabindex="-1">（二）功能启用操作 <a class="header-anchor" href="#二-功能启用操作" aria-label="Permalink to &quot;（二）功能启用操作&quot;">​</a></h3><p>用户只需点击界面中的 “点击这里启用” 绿色按钮，即可按照系统引导流程逐步完成两步验证功能的启用和配置。配置过程通常包括绑定身份验证应用程序（如 Google Authenticator、Duo 等）、生成并保存备用验证代码等步骤，以便在无法获取动态验证代码时，仍能顺利登录账户。</p><p>通过启用两步验证功能并遵循相关注意事项，用户能够显著增强平台账户的安全性，有效防范账户被盗、信息泄露等风险，为账户及相关业务操作提供坚实的安全保障。</p>',10)])])}const _=a(s,[["render",i]]);export{u as __pageData,_ as default};
